parameters.jsCode:
const email = $input.first().json;

// Extraction expéditeur
const fromArr = email.from?.value || [];
const from = fromArr[0] || {};
const senderName = from.name || '';
const senderEmail = from.address || email.from?.text || '';

// Extraction contenu
const subject = email.subject || '(Sans objet)';
const rawText = email.textPlain || email.snippet || '';
const snippet = rawText.slice(0, 600).replace(/\n+/g, ' ').trim();
const dateMs = email.internalDate ? parseInt(email.internalDate) : Date.now();
const date = new Date(dateMs).toISOString();
const hasAttachment = (email.attachments || []).length > 0;
const emailId = email.id || '';
const threadId = email.threadId || '';

// Prompt pour l'IA
const aiContext = `Tu es un assistant de tri d'emails pour captain@netroia.com.
NetroIA est une agence spécialisée en automatisation n8n et systèmes IA agentiques B2B.

Analyse cet email et retourne une classification JSON.

Expéditeur : ${senderName} <${senderEmail}>
Objet : ${subject}
Contenu (extrait) : ${snippet}
Date : ${date}
Pièces jointes : ${hasAttachment ? 'Oui' : 'Non'}

Types de classification disponibles :
- CLIENT_POTENTIEL : prospect cherchant un devis, une démo, un partenariat, ou exprimant un besoin d'automatisation/IA
- CLIENT_EXISTANT : client actuel avec une demande, question ou mise à jour de projet
- IMPORTANT : email professionnel nécessitant une réponse (partenariat stratégique, presse, admin, juridique, facture urgente)
- NEWSLETTER : newsletter, update produit, contenu éditorial sur abonnement
- COMMERCIAL : cold email, prospection commerciale non sollicitée, publicité
- SPAM : spam, phishing, non pertinent`;

return [{
  json: {
    sender_name: senderName,
    sender_email: senderEmail,
    subject,
    snippet,
    date,
    has_attachment: hasAttachment,
    email_id: emailId,
    thread_id: threadId,
    ai_context: aiContext
  }
}];

parameters.inputSchema:
{
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "type_email": {
      "type": "string",
      "enum": ["CLIENT_POTENTIEL", "CLIENT_EXISTANT", "IMPORTANT", "NEWSLETTER", "COMMERCIAL", "SPAM"],
      "description": "Classification du type d'email"
    },
    "priorite": {
      "type": "string",
      "enum": ["HAUTE", "MOYENNE", "BASSE"],
      "description": "Niveau de priorité de traitement"
    },
    "resume": {
      "type": "string",
      "description": "Résumé de l'email en 1-2 phrases maximum"
    },
    "action_recommandee": {
      "type": "string",
      "description": "Action recommandée parmi : Répondre rapidement / Répondre / Ignorer / Archiver / Transférer"
    },
    "score_interet": {
      "type": "integer",
      "minimum": 0,
      "maximum": 10,
      "description": "Score d'intérêt commercial de 0 (nul) à 10 (critique)"
    }
  },
  "required": ["type_email", "priorite", "resume", "action_recommandee", "score_interet"]
}

